from harvests import load_harvests, ROWS
from podium import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_harvests()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_harvests()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_harvests()))
    assert [x.kilos for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_harvests())
    podium(data, 2)
    assert [x.kilos for x in data] == VALUES


def test_one_place():
    assert [x.kilos for x in podium(list(load_harvests()), 1)] == [max(VALUES)]
